const fs = require('fs');
const path = require('path');

const srcDir = path.join(__dirname, 'src');

function replaceInFile(filePath) {
  let content = fs.readFileSync(filePath, 'utf8');
  // First, let's see if we can just define a helper or replace exactly.
  // There are two common patterns:
  // fetch('http://localhost:5000/api/...')
  // axios.get('http://localhost:5000/api/...')
  // We want to replace 'http://localhost:5000' with (import.meta.env.VITE_API_URL || "http://localhost:5000")
  // But doing a direct string replace inside templates could be tricky.
  // Wait, if we define: const API_URL = import.meta.env.VITE_API_URL || "http://localhost:5000"; at the top of files that have it, and then use `${API_URL}/api...`
  // Actually, replacing `http://localhost:5000` with `${import.meta.env.VITE_API_URL || "http://localhost:5000"}` in backticks, or replacing `'http://localhost:5000/api/...'` with `(import.meta.env.VITE_API_URL || "http://localhost:5000") + '/api/...'` is safer.

  // A safer approach: find all instances of 'http://localhost:5000' and "http://localhost:5000" and replace with `(import.meta.env.VITE_API_URL || "http://localhost:5000")`
  // And `http://localhost:5000` inside backticks `${"http://localhost:5000"}` ?
  // Let's just use string concatenation for simplicity if it's in a quote.

  let modified = false;

  // Replace "http://localhost:5000" + or 'http://localhost:5000' +
  const regexDouble = /"http:\/\/localhost:5000([^"]*)"/g;
  const regexSingle = /'http:\/\/localhost:5000([^']*)'/g;
  const regexBacktick = /`http:\/\/localhost:5000([^`]*)`/g;

  if (regexDouble.test(content) || regexSingle.test(content) || regexBacktick.test(content)) {
    content = content.replace(regexDouble, '`${import.meta.env.VITE_API_URL || "http://localhost:5000"}$1`');
    content = content.replace(regexSingle, '`${import.meta.env.VITE_API_URL || "http://localhost:5000"}$1`');
    content = content.replace(regexBacktick, '`${import.meta.env.VITE_API_URL || "http://localhost:5000"}$1`');

    fs.writeFileSync(filePath, content, 'utf8');
    console.log(`Updated ${filePath}`);
  }
}

function traverse(dir) {
  const files = fs.readdirSync(dir);
  for (const file of files) {
    const fullPath = path.join(dir, file);
    if (fs.statSync(fullPath).isDirectory()) {
      traverse(fullPath);
    } else if (fullPath.endsWith('.jsx') || fullPath.endsWith('.js')) {
      replaceInFile(fullPath);
    }
  }
}

traverse(srcDir);

